201	            Person holder = holders.apply(share.getPersonId());
202	            BigDecimal part = holder == null ? null
203	                    : partOf(claim, share, due, holder, sheetRates, sheet, roundingClaims);
204	            total = part == null ? total : total.add(part);
205	        }
206	        return total;
207	    }
208	
209	    /** A holder's part of a claim with this due: a settled claim keeps its parts frozen, its settled due times the
210	     *  holder's share divided by 100, rounded half to even; any other claim's is its amount times the holder's share
211	     *  divided by 100, times the rate of the holder's own grade in force on the claim's date divided by 100, rounded
212	     *  as the claim rounds; null when their grade has no rate then. */
213	    public static BigDecimal partOf(Claim claim, ClaimShare share, BigDecimal due, Person holder,
214	            RateChain sheetRates, Sheet sheet, Collection<Claim> roundingClaims) {
215	        if (claim.getSettledDue() != null) {
216	            return share.partOf(due);
217	        }
218	        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN
219	                : sheet.roundingFor(ClaimService.roundingDate(claim, roundingClaims));
220	        return sheetRates.inForceOn(holder.gradeOn(claim.getDate()), claim.getDate(), claim.getId())
221	                .map(rate -> share.partOf(claim.getAmount(), rate.getRate(), rounding))
222	                .orElse(null);
223	    }
224	
225	    /** A person's score, as the screen shows it. */
226	    public record PersonScore(String name, long score) {
227	    }
228	
229	    /** Each person's score on the sheet's today as the store holds it now, by id in list order, as the screen shows
230	     *  it: the dues of their SETTLED claims that count and correct nothing, less 500.00 for each of their overdue claims that count,
231	     *  divided by 100 and rounded half to even to a whole number. */
232	    public Map<Long, PersonScore> scoresOf(String sheetId) {
233	        Sheet sheet = sheets.findById(sheetId).orElse(null);
234	        LocalDate today = sheet == null ? null : sheet.getToday();
235	        RateChain sheetRates = rates.of(sheetId);
236	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
237	        Map<Long, PersonScore> byPerson = new LinkedHashMap<>();
238	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
239	            List<Claim> counting = sheetClaims.stream()
240	                    .filter(c -> c.getPersonId().equals(person.getId()) && person.counts(c, today)
241	                            && !c.isDeferredOn(today))
242	                    .toList();
243	            BigDecimal settled = counting.stream()
244	                    .filter(c -> c.getStatus() == ClaimStatus.SETTLED && c.getCorrects() == null)
245	                    .map(c -> dueOf(c, person.gradeOn(c.getDate()), sheetRates, sheet, sheetClaims))
246	                    .filter(Objects::nonNull)
247	                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
248	            long overdue = counting.stream()
249	                    .filter(c -> today != null && ClaimService.isOverdue(c, sheet, person.gradeOn(c.getDate())))
250	                    .count();
251	            BigDecimal score = settled.subtract(BigDecimal.valueOf(500 * overdue))
252	                    .divide(BigDecimal.valueOf(100))
253	                    .setScale(0, RoundingMode.HALF_EVEN);
254	            byPerson.put(person.getId(), new PersonScore(person.getName(), score.longValueExact()));
255	        }
256	        return byPerson;
257	    }
258	
259	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
260	    static BigDecimal trimmedSum(List<BigDecimal> figures) {
261	        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
262	        if (figures.size() < 3) {
263	            return sum;
264	        }
265	        BigDecimal highest = figures.stream().max(BigDecimal::compareTo).orElseThrow();
266	        BigDecimal lowest = figures.stream().min(BigDecimal::compareTo).orElseThrow();
267	        return sum.subtract(highest).subtract(lowest);
268	    }
269	
270	    /** Each person's due-total for the dates from {@code from} to {@code to} inclusive, by person id, as the screen
271	     *  shows a person's period figure: the dues as shown now of their claims that counted by the status they had at the end
272	     *  of {@code to} (a held person's open ones dated within a
273	     *  hold and not stated do not) due by in it, none counting as 0; every person on the sheet has one. */
274	    public Map<Long, BigDecimal> dueByPersonBetween(String sheetId, LocalDate from, LocalDate to) {
275	        RateChain sheetRates = rates.of(sheetId);
276	        Sheet sheet = sheets.findById(sheetId).orElse(null);
277	        LocalDate today = sheet == null ? null : sheet.getToday();
278	        Map<Long, Person> personOf = new LinkedHashMap<>();
279	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
280	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
281	            personOf.put(p.getId(), p);
282	            totals.put(p.getId(), BigDecimal.ZERO.setScale(2));
283	        });
284	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
285	        for (Claim claim : sheetClaims) {
286	            Person person = personOf.get(claim.getPersonId());
287	            if (person == null || !person.countsAtEnd(claim, to, today) || claim.isDeferredOn(today) || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)) {
288	                continue;
289	            }
290	            BigDecimal due = dueOf(claim, person.gradeOn(claim.getDate()), sheetRates, sheet, sheetClaims);
291	            if (due != null) {
292	                totals.merge(person.getId(), due, BigDecimal::add);
293	            }
294	        }
295	        return totals;
296	    }
297	
298	    /** Each person's carried figure for a period, by person id, as the screen shows it: the dues as shown now of
299	     *  their claims that count (as for the period's figures) which are due by in a period of the sheet ending before
300	     *  this one starts and were still OPEN or PENDING at the end of this period's last day, none counting as 0, plus
301	     *  their opening balance for it; every person on the sheet has one. */
302	    public Map<Long, BigDecimal> carriedByPerson(String sheetId, Period period) {
303	        RateChain sheetRates = rates.of(sheetId);
304	        Sheet sheet = sheets.findById(sheetId).orElse(null);
305	        LocalDate today = sheet == null ? null : sheet.getToday();
306	        LocalDate end = period.getToDate();
307	        List<Period> sheetPeriods = periods.findBySheetIdOrderByFromDateAsc(sheetId);
308	        Map<Long, Person> personOf = new LinkedHashMap<>();
309	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
310	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
311	            personOf.put(p.getId(), p);
312	            totals.put(p.getId(), period.openingOf(p.getId()));
313	        });
314	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
315	        for (Claim claim : sheetClaims) {
316	            Person person = personOf.get(claim.getPersonId());
317	            if (person == null || !person.countsAtEnd(claim, end, today) || claim.isDeferredOn(today)) {
318	                continue;
319	            }
320	            ClaimStatus status = claim.statusAt(end);
321	            if (status != ClaimStatus.OPEN && status != ClaimStatus.PENDING) {
322	                continue;
323	            }
324	            boolean earlier = sheetPeriods.stream().filter(p -> p.contains(claim.getDueBy())).findFirst()
325	                    .map(own -> own.getToDate().isBefore(period.getFromDate())).orElse(false);
326	            if (!earlier) {
327	                continue;
328	            }
329	            BigDecimal due = dueOf(claim, person.gradeOn(claim.getDate()), sheetRates, sheet, sheetClaims);
330	            if (due != null) {
331	                totals.merge(person.getId(), due, BigDecimal::add);
332	            }
333	        }
334	        return totals;
335	    }
336	
337	    /** Each person's open figure at {@code end}, by person id: the dues as shown now of their claims that count (as for
338	     *  the period's figures) which are due by in one of {@code yearPeriods} and were still OPEN or PENDING at the end
339	     *  of {@code end}, none counting as 0; every person on the sheet has one. */
340	    public Map<Long, BigDecimal> openByPersonAt(String sheetId, List<Period> yearPeriods, LocalDate end) {
341	        RateChain sheetRates = rates.of(sheetId);
342	        Sheet sheet = sheets.findById(sheetId).orElse(null);
343	        LocalDate today = sheet == null ? null : sheet.getToday();
344	        Map<Long, Person> personOf = new LinkedHashMap<>();
345	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
346	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
347	            personOf.put(p.getId(), p);
348	            totals.put(p.getId(), BigDecimal.ZERO.setScale(2));
349	        });
350	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
351	        for (Claim claim : sheetClaims) {
352	            Person person = personOf.get(claim.getPersonId());
353	            if (person == null || !person.countsAtEnd(claim, end, today) || claim.isDeferredOn(today)) {
354	                continue;
355	            }
356	            ClaimStatus status = claim.statusAt(end);
357	            if (status != ClaimStatus.OPEN && status != ClaimStatus.PENDING) {
358	                continue;
359	            }
360	            if (yearPeriods.stream().noneMatch(p -> p.contains(claim.getDueBy()))) {
361	                continue;
362	            }
363	            BigDecimal due = dueOf(claim, person.gradeOn(claim.getDate()), sheetRates, sheet, sheetClaims);
364	            if (due != null) {
365	                totals.merge(person.getId(), due, BigDecimal::add);
366	            }
367	        }
368	        return totals;
369	    }
370	
371	    /** What a candidate rate would change: how many claims would show a different due, and the sum of the
372	     *  differences (new due minus current due), with two decimals. */
373	    public record RatePreview(int count, String diff) {
374	    }
375	
376	    /** How the OPEN and PENDING claims of people on a grade (in force on each claim's date) would change were a rate
377	     *  to apply to that grade on every date: a claim bound by a statement does not change and a settled one is not
378	     *  counted; a due of none counts as 0 in the sum. Nothing is stored. */
379	    public RatePreview preview(String sheetId, String grade, BigDecimal rate) {
380	        RateChain sheetRates = rates.of(sheetId);
381	        RateChain candidate = sheetRates.withOwn(Stream.concat(
382	                sheetRates.levels().get(0).stream().filter(r -> !r.getGrade().equals(grade)),
383	                Stream.of(new Rate(sheetId, grade, null, rate.setScale(2, RoundingMode.UNNECESSARY)))).toList());
384	        Sheet sheet = sheets.findById(sheetId).orElse(null);
385	        Map<Long, Person> personOf = new LinkedHashMap<>();
386	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> personOf.put(p.getId(), p));
387	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
388	        int count = 0;
389	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
390	        for (Claim claim : sheetClaims) {
391	            Person person = personOf.get(claim.getPersonId());
392	            if (person == null || claim.getSettledDue() != null
393	                    || (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING)
394	                    || !grade.equals(person.gradeOn(claim.getDate()))) {
395	                continue;
396	            }
397	            BigDecimal now = dueOf(claim, grade, sheetRates, sheet, sheetClaims);
398	            BigDecimal then = dueOf(claim, grade, candidate, sheet, sheetClaims);
399	            if (!Objects.equals(now, then)) {
400	                count++;
401	                diff = diff.add(then == null ? BigDecimal.ZERO : then)
402	                        .subtract(now == null ? BigDecimal.ZERO : now);
403	            }
404	        }
405	        return new RatePreview(count, diff.setScale(2).toPlainString());
406	    }
407	
408	    /**
409	     * Record, once the change commits, how the sheet's figures moved since {@code before}: a ROLLUP line
410	     * for each person whose figures changed (one who did not exist before counting as changed), then a
411	     * TOTALS line if the sheet's totals changed, then the ALERT lines of the people who crossed the sheet's alert
412	     * threshold (see {@link #recordAlerts}). Nothing is recorded when no figure moved.
413	     */
414	    public void recordChanges(String sheetId, String user, Figures before) {
415	        Figures after = of(sheetId);
416	        after.people().forEach((id, figures) -> {
417	            PersonFigures was = before.people().get(id);
418	            if (was == null || !was.claimed().equals(figures.claimed()) || !was.dueTotal().equals(figures.dueTotal())
419	                    || !was.overdueTotal().equals(figures.overdueTotal())) {
420	                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
421	                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal()
422	                        + " overdue-total=" + figures.overdueTotal());
423	            }
424	        });
425	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
426	                || !before.overdueTotal().equals(after.overdueTotal())) {
427	            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
428	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
429	        }
430	        recordAlerts(sheetId, user, before, after);
431	    }
432	
433	    /**
434	     * Record, once the change commits, an ALERT line, in list order, for each person whose due-total went from at or
435	     * below the sheet's alert threshold (or none, or not being on the sheet) to above it between {@code before} (null:
436	     * nobody was) and {@code after}. Nothing is recorded while the threshold is off.
437	     */
438	    public void recordAlerts(String sheetId, String user, Figures before, Figures after) {
439	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
440	        if (threshold == null) {
441	            return;
442	        }
443	        after.people().forEach((id, figures) -> {
444	            PersonFigures was = before == null ? null : before.people().get(id);
445	            if (above(figures, threshold) && (was == null || !above(was, threshold))) {
446	                audit.recordOnCommit("ALERT sheet=" + sheetId + " by=" + user + " name=" + figures.name()
447	                        + " due-total=" + figures.dueTotal());
448	            }
449	        });
450	    }
451	
452	    private static boolean above(PersonFigures figures, BigDecimal threshold) {
453	        return !NOT_AVAILABLE.equals(figures.dueTotal()) && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
454	    }
455	
456	    /** A claim's due: its settled figure, else its stated one, else its amount at the rate in force on its date of
457	     *  its person's grade in force on that date (the sheet's own, else its nearest ancestor's), rounded as the claim rounds (by the sheet's policy date) and raised to the floor in force on its date unless it is a
458	     *  correction; an overdue claim's late charge, worked out on that figure, is added on top of it. */
459	    private static BigDecimal dueOf(Claim claim, String grade, RateChain sheetRates, Sheet sheet, List<Claim> sheetClaims) {
460	        if (claim.getSettledDue() != null) {
461	            return claim.getSettledDue();
462	        }
463	        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN
464	                : sheet.roundingFor(ClaimService.roundingDate(claim, sheetClaims));
465	        BigDecimal figure = claim.isBound() ? claim.getBoundDue()
466	                : sheetRates.inForceOn(grade, claim.getDate(), claim.getId())
467	                        .map(rate -> ClaimService.floored(claim, ClaimService.liveFigure(claim, rate.getRate(), rounding), sheet))
468	                        .orElse(null);
469	        return figure == null || sheet == null ? figure
470	                : figure.add(ClaimService.lateCharge(claim, figure, sheet, grade));
471	    }
472	}
