37	/** A sheet's descendants' figures, which the screen adds to the sheet's own to show them consolidated. */
38	@RestController
39	@Validated
40	@RequestMapping("/api/sheets/{sheetId}/descendants")
41	public class ConsolidatedController {
42	
43	    /** The figures of the sheet's descendants (its children, their children and so on; not the sheet itself) added
44	     *  up: how many people, each person counted once however many sheets they are on (people whose names or aliases
45	     *  match as names are compared being one); the due-totals and overdue-totals of all their people, trimmed once of
46	     *  the single highest and lowest person's figure when three or more have one, with two decimals; each person's
47	     *  names and figures, so the screen can count and trim its own people with them; per grade, the due-totals of the people not retired on it on their sheet's today (none counting as 0), with
48	     *  two decimals; per claim status, how many claims are in it; and how many claims that count are overdue on
49	     *  their sheet's today. */
50	    public record DescendantFigures(int peopleCount, String dueTotal, String overdueTotal,
51	            Map<String, String> dueByGrade, Map<String, Integer> countByStatus, List<PersonFigure> people,
52	            int overdueCount) {
53	    }
54	
55	    /** A person of the tree: their name and aliases, their due-total (null when they have none) and overdue-total as
56	     *  their sheet shows them, with two decimals. */
57	    public record PersonFigure(List<String> names, String dueTotal, String overdueTotal) {
58	    }
59	
60	    private final SheetRepository sheets;
61	    private final Rollup rollup;
62	    private final SheetHistory history;
63	    private final RateChains rates;
64	    private final PersonRepository people;
65	    private final ClaimRepository claims;
66	    private final PoolService pools;
67	
68	    public ConsolidatedController(SheetRepository sheets, Rollup rollup, SheetHistory history, RateChains rates,
69	            PersonRepository people, ClaimRepository claims, PoolService pools) {
70	        this.pools = pools;
71	        this.sheets = sheets;
72	        this.rollup = rollup;
73	        this.history = history;
74	        this.rates = rates;
75	        this.people = people;
76	        this.claims = claims;
77	    }
78	
79	    /** A sheet of the tree as counted: its figures, and the people and claims they were worked out from. */
80	    private record Counted(Sheet sheet, Rollup.Figures figures, List<Person> people, List<Claim> claims) {
81	    }
82	
83	    /** With {@code self}, the sheet's own figures are added in too. While the screen shows the sheet as of a date,
84	     *  each sheet of the tree (as it names its parent now) counts as it stood at the end of that date, that date
85	     *  standing in for its today; one with no change made on it by then has no one on it. While the screen previews a
86	     *  date, each sheet of the tree counts over its current records with that date standing in for its today. */
87	    @GetMapping("/figures")
88	    @Transactional(readOnly = true)
89	    public DescendantFigures figures(
90	            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
91	            @RequestParam(defaultValue = "false") boolean self,
92	            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf,
93	            @RequestHeader(value = Preview.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate preview) {
94	        List<PersonFigure> treePeople = new ArrayList<>();
95	        Map<String, BigDecimal> dueByGrade = new LinkedHashMap<>();
96	        Map<String, Integer> countByStatus = new LinkedHashMap<>();
97	        int overdueCount = 0;
98	        List<String> counted = new ArrayList<>(sheets.descendantsOf(sheetId));
99	        if (self) {
100	            counted.add(0, sheetId);
101	        }
102	        for (String descendant : counted) {
103	            Counted one = asOf == null ? live(descendant, preview) : countedAsOf(descendant, asOf);
104	            if (one == null) {
105	                continue;
106	            }
107	            Rollup.Figures figures = one.figures();
108	            LocalDate today = one.sheet() == null ? null : one.sheet().getToday();
109	            for (Person person : one.people()) {
110	                if (today != null) {
111	                    overdueCount += (int) one.claims().stream()
112	                            .filter(c -> c.getPersonId().equals(person.getId()) && person.counts(c, today)
113	                                    && !c.isDeferredOn(today)
114	                                    && ClaimService.isOverdue(c, one.sheet(), person.gradeOn(c.getDate())))
115	                            .count();
116	                }
117	                Rollup.PersonFigures own = figures.people().get(person.getId());
118	                if (own != null) {
119	                    List<String> names = new ArrayList<>();
120	                    names.add(person.getName());
121	                    names.addAll(person.getAliases());
122	                    treePeople.add(new PersonFigure(names, "n/a".equals(own.dueTotal()) ? null : own.dueTotal(),
123	                            own.overdueTotal()));
124	                }
125	                if (person.isRetired() || own == null || "n/a".equals(own.dueTotal())) {
126	                    continue;
127	                }
128	                dueByGrade.merge(person.gradeOn(today), new BigDecimal(own.dueTotal()), BigDecimal::add);
129	            }
130	            for (Claim claim : one.claims()) {
131	                countByStatus.merge(claim.getStatus().name(), 1, Integer::sum);
132	            }
133	        }
134	        Map<String, String> dueByGradeShown = new LinkedHashMap<>();
135	        dueByGrade.forEach((grade, total) -> dueByGradeShown.put(grade, total.setScale(2).toPlainString()));
136	        BigDecimal due = Rollup.trimmedSum(treePeople.stream().map(PersonFigure::dueTotal).filter(Objects::nonNull)
137	                .map(BigDecimal::new).toList());
138	        BigDecimal overdue = Rollup.trimmedSum(treePeople.stream().map(p -> new BigDecimal(p.overdueTotal())).toList());
139	        return new DescendantFigures(distinctPeople(treePeople), due.toPlainString(), overdue.toPlainString(),
140	                dueByGradeShown, countByStatus, treePeople, overdueCount);
141	    }
142	
143	    /** How many distinct people these are: those sharing a name or alias, as names are compared (trimmed, case
144	     *  ignored), directly or through others, being one. */
145	    static int distinctPeople(List<PersonFigure> treePeople) {
146	        int[] parent = new int[treePeople.size()];
147	        for (int i = 0; i < parent.length; i++) {
148	            parent[i] = i;
149	        }
150	        Map<String, Integer> firstWithName = new HashMap<>();
151	        int distinct = parent.length;
152	        for (int i = 0; i < parent.length; i++) {
153	            for (String name : treePeople.get(i).names()) {
154	                Integer other = firstWithName.putIfAbsent(name.trim().toLowerCase(Locale.ROOT), i);
155	                if (other != null) {
156	                    int a = root(parent, i), b = root(parent, other);
157	                    if (a != b) {
158	                        parent[a] = b;
159	                        distinct--;
160	                    }
161	                }
162	            }
163	        }
164	        return distinct;
165	    }
166	
167	    private static int root(int[] parent, int i) {
168	        while (parent[i] != i) {
169	            i = parent[i] = parent[parent[i]];
170	        }
171	        return i;
172	    }
173	
174	    /** A sheet as the store holds it now; with a preview date (else null), that date standing in for its today. */
175	    private Counted live(String sheetId, LocalDate preview) {
176	        Sheet sheet = sheets.findById(sheetId).orElse(null);
177	        List<Person> sheetPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
178	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
179	        return new Counted(Preview.of(sheet, preview),
180	                rollup.previewed(sheet, rates.of(sheetId), sheetPeople, sheetClaims, preview), sheetPeople,
181	                sheetClaims);
182	    }
183	
184	    /** A sheet's figures as it stood at the end of a date, that date as its today; none when no change was made on it
185	     *  by then. */
186	    private Counted countedAsOf(String sheetId, LocalDate asOf) {
187	        Sheet live = sheets.findById(sheetId).orElse(null);
188	        SheetState then = live == null ? null : history.asOf(sheetId, asOf).orElse(null);
189	        if (then == null) {
190	            return null;
191	        }
192	        Sheet sheet = then.rebuildSheet(live, asOf);
193	        List<Person> sheetPeople = then.rebuildPeople(sheetId);
194	        List<Claim> sheetClaims = then.rebuildClaims(sheetId);
195	        return new Counted(sheet, rollup.of(sheet, history.ratesAsOf(sheetId, asOf), sheetPeople, sheetClaims,
196	                        pools.cutTotals(sheetId, asOf)),
197	                sheetPeople, sheetClaims);
198	    }
199	}
