/** A person's own terms from the beginning of time as the form shows them: blank for none. */
function termsText(p: PersonView): string {
  const terms = p.undatedTerms === undefined ? p.terms : p.undatedTerms;
  return terms === null ? '' : String(terms);
}

/** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
function trimmedSum(figures: number[]): number {
  const sum = figures.reduce((total, f) => total + f, 0);
  return figures.length < 3 ? sum : sum - Math.max(...figures) - Math.min(...figures);
}

/** A CSV field: wrapped in double quotes, with any quote inside doubled, when it holds a comma, a quote or a line break. */
function csvField(value: string): string {
  return /[",\r\n]/.test(value) ? '"' + value.replaceAll('"', '""') + '"' : value;
}

/** The cells of a person's row its CSV export holds, in order. */
const EXPORT_CELLS = [
  'person-name', 'person-grade', 'person-claimed', 'person-due-total', 'person-statement-count',
  'person-overdue-total', 'person-hold', 'person-retired', 'person-aliases', 'person-score',
] as const;

// The people on the active sheet: one form to add a person or edit an existing one, the list with
// each person's claims and due-total, and the sheet's claimed-total and due-total.

@Component({
  selector: 'app-people',
  imports: [ReactiveFormsModule, FigurePipe, SheetHeader, PersonClaims, PeriodsPanel, SummaryPanel, ClassicSummaryPanel, SheetComparePanel, PoolsPanel, CrewsPanel, PersonPlans, PlanGenerate, Dashboard],
  template: `
    <app-header [peopleCount]="people().length" [statuses]="summaryByStatus()" [dueTotal]="dueTotal()"
                [overdueTotal]="money(overdueTotals().cents)" [myDueTotal]="me() ? dueOf(me()!) : ''"
                [myOverdueTotal]="me() ? money(overdueOf(me()!.id).cents) : ''"
                [myCrewDueTotal]="myCrewDueTotal()" [myReviewsCount]="myReviewsCount()"
                [watchedDueTotal]="watchedDueTotal()" />
    <app-dashboard [pending]="treeStatusCount('PENDING')" [review]="treeStatusCount('REVIEW')"
                   [overdue]="overdueTotals().count + descendants().overdueCount" />
    <app-periods [dueTotals]="dueByPeriod()" />
    <app-pools [people]="people()" />
    <app-crews [people]="people()" [dueByPerson]="dueByPerson()" />
    <app-summary [grades]="summaryByGrade()" [periods]="summaryByPeriod()" [statuses]="summaryByStatus()"
                 [voidReasons]="summaryByVoidReason()" [reviewLate]="reviewLateCount()"
                 [pendingLate]="pendingLateCount()" />
    <app-classic-summary [periods]="classicByPeriod()" [dueTotal]="classicDueTotal()" />
    <app-sheet-compare [grades]="summaryByGrade()" />

    <section aria-labelledby="people-heading">
      <h2 id="people-heading">People</h2>
      <p>Consolidated over this sheet and its descendants:
        people <strong data-testid="consolidated-people-count">{{ consolidated().peopleCount }}</strong>,
        due <strong data-testid="consolidated-due-total">{{ (consolidated().dueTotal) | figure }}</strong>,
        overdue <strong data-testid="consolidated-overdue-total">{{ (consolidated().overdueTotal) | figure }}</strong></p>
      <ul aria-label="Consolidated by grade">
        @for (g of consolidated().grades; track g.grade) {
          <li>Grade {{ g.grade }}: due
            <strong [attr.data-testid]="'consolidated-grade-' + g.grade + '-due-total'">{{ (g.dueTotal) | figure }}</strong></li>
        }
      </ul>
      <ul aria-label="Consolidated by status">
        @for (s of consolidated().statuses; track s.status) {
          <li>{{ s.status }}:
            <strong [attr.data-testid]="'consolidated-status-' + s.status + '-count'">{{ s.count }}</strong> claims</li>
        }
      </ul>
      <p>Claimed in total: <strong data-testid="rollup-claimed-total">{{ (claimedTotal()) | figure }}</strong></p>
      <p>Due in total: <strong data-testid="rollup-due-total">{{ (dueTotal()) | figure }}</strong></p>
      <p>Overdue: <strong data-testid="rollup-overdue-count">{{ overdueTotals().count }}</strong>
        claims, due <strong data-testid="rollup-overdue-total">{{ (money(overdueTotals().cents)) | figure }}</strong></p>
      <p>Settled in total: <strong data-testid="rollup-settled-total">{{ (money(splitTotals().settled)) | figure }}</strong>,
        open in total: <strong data-testid="rollup-open-total">{{ (money(splitTotals().open)) | figure }}</strong></p>
      <p>Cut in total: <strong data-testid="rollup-cut-total">{{ (money(cutTotal())) | figure }}</strong></p>
      <p>Aged 0–30: <strong data-testid="rollup-aged-0-30">{{ (money(agedTotals().upTo30)) | figure }}</strong>,
        31–60: <strong data-testid="rollup-aged-31-60">{{ (money(agedTotals().upTo60)) | figure }}</strong>,
        61+: <strong data-testid="rollup-aged-61">{{ (money(agedTotals().over60)) | figure }}</strong></p>
      @if (tagTotals().length > 0) {
        <ul aria-label="Due by tag">
          @for (t of tagTotals(); track t.tag) {
            <li>{{ t.tag }}: <span [attr.data-testid]="'tag-' + t.tag + '-due-total'">{{ (money(t.cents)) | figure }}</span></li>
          }
        </ul>
      }
        }
      }
    }
    return byPerson;
  });
  /** Each person's due-total before the cap split by status, in whole cents: the dues of their SETTLED claims that
   *  count (at their frozen figures, corrections included) and of their OPEN and PENDING claims that count. */
  private readonly splitByPerson = computed(() => {
    const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
    const byPerson = new Map<number, Split>();
    for (const p of this.people()) {
      const split = { ...NO_SPLIT };
      for (const c of this.claimsOf(p.id).filter(countsWithHolds(p.holds, this.todayNow(), p.retiredFrom))) {
        const due = this.claimDue(p, c, dueTerms) ?? 0;
        if (c.status === 'SETTLED') {
          split.settled += this.ownPart(c, due, dueTerms);
          if (c.corrects == null) split.scored += due;
        }
        else if (c.status === 'OPEN' || c.status === 'PENDING') split.open += this.ownPart(c, due, dueTerms);
      }
      for (const h of this.heldParts().get(p.id) ?? []) {
        if (h.claim.status === 'SETTLED') split.settled += h.part;
        else if (h.claim.status === 'OPEN' || h.claim.status === 'PENDING') split.open += h.part;
      }
      byPerson.set(p.id, split);
    }
    return byPerson;
  });
  /** Each person's cut total in whole cents: their cuts across every pool they are a member of, added up; a pool
   *  that shows no cuts adds nothing. */
  private readonly cutByPerson = computed(() => {
    const byPerson = new Map<number, number>();
    for (const pool of this.pools.all()) {
      for (const m of pool.members) {
        if (m.personId !== null && m.cut !== null) {
          byPerson.set(m.personId, (byPerson.get(m.personId) ?? 0) + cents(m.cut));
        }
      }
    }
    return byPerson;
  });
  protected cutOf(personId: number): number {
    return this.cutByPerson().get(personId) ?? 0;
  }
  /** The sheet's cut total in whole cents: everyone's cut total added up. */
  protected readonly cutTotal = computed(() =>
    this.people().reduce((sum, p) => sum + this.cutOf(p.id), 0));
  /** Everyone's settled-total and open-total, each simply added up (not trimmed). */
  protected readonly splitTotals = computed(() => {
    const total = { ...NO_SPLIT };
    for (const split of this.splitByPerson().values()) {
      total.settled += split.settled;
      total.open += split.open;
    }
    return total;
  });
  /** For every tag used on the sheet's claims or people, in tag order, the dues in whole cents of the claims that
   *  count which carry it, or whose person does, once (none counting as 0); a claim with two tags counts in both. */
  protected readonly tagTotals = computed(() => {
    const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
    const totals = new Map<string, number>();
    for (const c of this.claims()) for (const tag of c.tags) totals.set(tag, 0);
    for (const p of this.people()) for (const tag of p.tags) totals.set(tag, 0);
    for (const p of this.people()) {
      for (const c of this.claimsOf(p.id).filter(countsWithHolds(p.holds, this.todayNow(), p.retiredFrom))) {
        const tags = new Set([...c.tags, ...p.tags]);
        if (tags.size === 0) continue;
        const due = this.claimDue(p, c, dueTerms) ?? 0;
        for (const tag of tags) totals.set(tag, (totals.get(tag) ?? 0) + due);
      }
    }
    return [...totals].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([tag, cents]) => ({ tag, cents }));
  });
  /** For every calendar month (yyyy-mm) any of the sheet's claims is dated in, in month order, the dues in whole
   *  cents of the claims dated in it that count (none counting as 0). */
  protected readonly monthTotals = computed(() => {
    const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
    const totals = new Map<string, number>();
    for (const c of this.claims()) totals.set(c.date.slice(0, 7), 0);
    for (const p of this.people()) {
      for (const c of this.claimsOf(p.id).filter(countsWithHolds(p.holds, this.todayNow(), p.retiredFrom))) {
        const month = c.date.slice(0, 7);
        totals.set(month, (totals.get(month) ?? 0) + (this.claimDue(p, c, dueTerms) ?? 0));
      }
    }
    return [...totals].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([month, cents]) => ({ month, cents }));
  });
  /** Everyone's due-total added up, skipping those with none, trimmed of the highest and lowest. */
  protected readonly dueTotal = computed(() =>
    money(trimmedSum([...this.dueByPerson().values()].filter((due) => due !== null))),
  );
  /** Over the sheet's own people as shown here and its descendants': how many distinct people (those whose names or
   *  aliases match as names are compared being one), and everyone's due-total and overdue-total trimmed once of the
   *  highest and lowest; the sheet's own per-grade due-totals and per-status claim counts added to its descendants';
   *  while the sheet is shown as of a date, its descendants' are as they stood then too. */
  protected readonly consolidated = computed(() => {
    const d = this.descendants();
    const dueByPerson = this.dueByPerson();
    const overdueByPerson = this.overdueByPerson();
    const tree = [
      ...this.people().map((p) => ({
        names: [p.name, ...(p.aliases ?? [])],
        due: dueByPerson.get(p.id) ?? null,
        overdue: overdueByPerson.get(p.id)?.cents ?? 0,
      })),
      ...d.people.map((p) => ({
        names: p.names,
        due: p.dueTotal === null ? null : cents(p.dueTotal),
        overdue: cents(p.overdueTotal),
      })),
    ];
    return {
      peopleCount: distinctPeople(tree),
      dueTotal: money(trimmedSum(tree.map((p) => p.due).filter((due) => due !== null))),
      overdueTotal: money(trimmedSum(tree.map((p) => p.overdue))),
      grades: this.summaryByGrade().map((g) => ({
        grade: g.grade,
        dueTotal: money(cents(g.dueTotal) + cents(d.dueByGrade[g.grade] ?? '0.00')),
      })),
      statuses: this.summaryByStatus().map((s) => ({ status: s.status, count: s.count + (d.countByStatus[s.status] ?? 0) })),
    };
  });
  /** Each person's overdue claims that count: how many, and their dues added up in whole cents (none counting as 0). */
  private readonly overdueByPerson = computed(() => {
    const sheet = this.sheets.current();
    const dueTerms = sheet ?? DEFAULT_DUE_TERMS;
    const byPerson = new Map<number, Overdue>();
    for (const p of this.people()) {
      const overdue = sheet
        ? this.claimsOf(p.id).filter((c) => countsWithHolds(p.holds, sheet.today, p.retiredFrom)(c) && isOverdue(c, sheet.today, graceOn(sheet.settings, gradeOn(p, c.date), c.date)))
        : NO_CLAIMS;
      byPerson.set(p.id, {
        count: overdue.length,
        cents: overdue.reduce((sum, c) => sum + (this.claimDue(p, c, dueTerms) ?? 0), 0),
      });
    }
    return byPerson;
  });
  /** Each person's aged dues: their OPEN and PENDING claims that count, by age in days on the sheet's today. */
  private readonly agedByPerson = computed(() => {
    const today = this.todayNow();
    const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
    const byPerson = new Map<number, Aged>();
    for (const p of this.people()) {
      const aged = { ...NO_AGED };
      if (today) {
        for (const c of this.claimsOf(p.id).filter(countsWithHolds(p.holds, today, p.retiredFrom))) {
          if (c.status !== 'OPEN' && c.status !== 'PENDING') continue;
          const due = this.claimDue(p, c, dueTerms) ?? 0;
          const age = Math.round((Date.parse(today) - Date.parse(c.date)) / 86_400_000);
          if (age <= 30) aged.upTo30 += due;
          else if (age <= 60) aged.upTo60 += due;
          else aged.over60 += due;
        }
      }
      byPerson.set(p.id, aged);
    }
    return byPerson;
  });
  /** Everyone's aged dues added up, bucket by bucket, not trimmed. */
  protected readonly agedTotals = computed(() =>
    [...this.agedByPerson().values()].reduce(
      (sum, a) => ({ upTo30: sum.upTo30 + a.upTo30, upTo60: sum.upTo60 + a.upTo60, over60: sum.over60 + a.over60 }),
      { ...NO_AGED },
    ),
  );
  /** Everyone's overdue claims added up: the count of them all, the dues trimmed of the highest and lowest person's. */
  protected readonly overdueTotals = computed(() => {
    const overdue = [...this.overdueByPerson().values()];
    return {
      count: overdue.reduce((sum, o) => sum + o.count, 0),
      cents: trimmedSum(overdue.map((o) => o.cents)),
    };
  });
  /** Each person's due-total for each period, in whole cents, by person id then period id: the dues as shown now
   *  of their claims whose due-by falls in it and that counted by the status they had at the end of its last day
   *  (none counting as 0); a closed or soft-closed period keeps the figures fixed when it was closed, 0 for a person added since. */
  private readonly dueByPersonPeriod = computed(() =>
    this.figuresByPersonPeriod((p, end) => countsAtEndWithHolds(p.holds, this.todayNow(), end, p.retiredFrom)));
  /** Each person's due-total for each period, by person id then period id, as `figuresByPersonPeriod` adds it up
   *  with the claims that count chosen by `counting` for the person and the period's last day. */
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

/** A sheet's descendants' figures added up (not the sheet's own): how many people (each counted once, those whose
 *  names or aliases match as names are compared being one), and the due-total and overdue-total of all their people
 *  trimmed once of the highest and lowest (two decimals); each of those people's names and figures; per grade, the due-totals of the people not
 *  retired on it (two decimals; a grade no one counts on is missing); and per claim status, how many claims are in
 *  it (a status no claim is in is missing); and how many claims that count are overdue on their sheet's today. */
export interface DescendantFigures {
  peopleCount: number;
  dueTotal: string;
  overdueTotal: string;
  dueByGrade: Record<string, string>;
  countByStatus: Record<string, number>;
  people: TreePerson[];
  overdueCount: number;
}

/** A person of the tree: their name and aliases, their due-total (null with none) and overdue-total as their sheet
 *  shows them (two decimals). */
export interface TreePerson {
  names: string[];
  dueTotal: string | null;
  overdueTotal: string;
}

/** How many distinct people these are: those sharing a name or alias, as names are compared (trimmed, case
 *  ignored), directly or through others, being one. */
export function distinctPeople(people: { names: string[] }[]): number {
  const parent = people.map((_, i) => i);
  const root = (i: number): number => (parent[i] === i ? i : (parent[i] = root(parent[i])));
  const firstWithName = new Map<string, number>();
  let distinct = people.length;
  people.forEach((p, i) => {
    for (const name of p.names) {
      const key = name.trim().toLowerCase();
      const other = firstWithName.get(key);
      if (other === undefined) {
        firstWithName.set(key, i);
        continue;
      }
      const a = root(i), b = root(other);
      if (a !== b) {
        parent[a] = b;
        distinct--;
      }
    }
  });
  return distinct;
}

/** No descendants: nothing to add to a sheet's own figures. */
export const NO_DESCENDANTS: DescendantFigures = {
  peopleCount: 0, dueTotal: '0.00', overdueTotal: '0.00', dueByGrade: {}, countByStatus: {}, people: [], overdueCount: 0,
};

// A sheet's descendants (its children, the sheets naming it as their parent, and theirs and so on), whose figures
// the screen adds to the sheet's own to show them consolidated.
@Injectable({ providedIn: 'root' })
export class Consolidated {
  private readonly http = inject(HttpClient);

  /** With `self`, the sheet's own live figures are added in too. */
